import{_ as o,c as t,o as d,b2 as i}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"登录日志与登录失败锁定设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-16-logininfor-design.md","filePath":"superpowers/specs/2026-05-16-logininfor-design.md"}'),c={name:"superpowers/specs/2026-05-16-logininfor-design.md"};function a(r,e,l,n,s,h){return d(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="登录日志与登录失败锁定设计文档" tabindex="-1">登录日志与登录失败锁定设计文档 <a class="header-anchor vp-link" href="#登录日志与登录失败锁定设计文档" aria-label="Permalink to &quot;登录日志与登录失败锁定设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在 <code>quickboot</code> + <code>quick-ui</code> 中实现《登录日志需求文档》所述能力：登录行为可查、可排序、可筛选、单条/批量删除、清空、导出、按用户名解锁；并与<strong>登录失败计数 + 临时锁定</strong>联动（方案乙），满足「解锁有实际效果」的验收预期。</p><p>路径与权限以需求文档为真源：<code>/monitor/logininfor/*</code>、<code>monitor:logininfor:*</code>。</p><h2 id="_2-已确认决策摘要" tabindex="-1">2. 已确认决策摘要 <a class="header-anchor vp-link" href="#_2-已确认决策摘要" aria-label="Permalink to &quot;2. 已确认决策摘要&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>API 前缀与权限</td><td><code>/monitor/logininfor</code>，<code>monitor:logininfor:list/remove/unlock/export</code></td></tr><tr><td>HTTP 动词</td><td>与仓库约定一致：删除/清空用 <strong>POST</strong>；列表 <strong>GET</strong>；解锁 <strong>GET</strong>；导出 <strong>POST</strong>（与需求文档字面 <code>DELETE</code> 不一致，以本设计为准）</td></tr><tr><td>表字段语义</td><td>对齐若依：<code>status</code> + <code>msg</code>（描述），列表「状态」「描述」直接映射</td></tr><tr><td>登录写日志</td><td><code>/login</code> 成功与失败均写 <code>sys_logininfor</code>；写库异常不得阻断登录主流程</td></tr><tr><td>锁定与解锁</td><td>失败达阈值锁定；成功登录清零失败计数；解锁接口清除该用户锁定相关缓存条目</td></tr><tr><td>缓存实现</td><td><strong>仅通过 Spring <code>CacheManager</code> / <code>org.springframework.cache.Cache</code> 读写</strong>，禁止业务代码注入 <code>RedisTemplate</code>、<code>StringRedisTemplate</code> 或 <code>RedisConnectionFactory</code> 操作锁定数据</td></tr><tr><td>锁定策略参数</td><td>落在 <strong>参数设置（<code>sys_config</code>）</strong>，且均为 <strong>系统内置（<code>config_type=1</code>）</strong>，<strong>不允许删除</strong>；与现有 <code>SysConfigServiceImpl</code> 规则一致</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-范围" tabindex="-1">3.1 范围 <a class="header-anchor vp-link" href="#_3-1-范围" aria-label="Permalink to &quot;3.1 范围&quot;">​</a></h3><ul><li>表 <code>sys_logininfor</code> 与 Flyway 迁移。</li><li>监控模块：登录日志分页查询、导出、删除（含批量）、清空、解锁。</li><li>登录链路：写访问日志；失败计数与锁定；成功清零。</li><li><code>sys_config</code> 种子：登录锁定相关内置参数。</li><li><code>quick-ui</code>：API、路由、列表页、权限、菜单（与现有监控/系统管理风格一致）。</li></ul><h3 id="_3-2-非范围-本期不做" tabindex="-1">3.2 非范围（本期不做） <a class="header-anchor vp-link" href="#_3-2-非范围-本期不做" aria-label="Permalink to &quot;3.2 非范围（本期不做）&quot;">​</a></h3><ul><li>登出访问日志（旧栈若有，可二期对齐）。</li><li>直接暴露 Redis 命令或 <code>RedisTemplate</code> 给业务层。</li></ul><h2 id="_4-数据模型" tabindex="-1">4. 数据模型 <a class="header-anchor vp-link" href="#_4-数据模型" aria-label="Permalink to &quot;4. 数据模型&quot;">​</a></h2><h3 id="_4-1-sys-logininfor" tabindex="-1">4.1 <code>sys_logininfor</code> <a class="header-anchor vp-link" href="#_4-1-sys-logininfor" aria-label="Permalink to &quot;4.1 `sys_logininfor`&quot;">​</a></h3><p>建议字段（与需求列表一致，命名与 MySQL 习惯及现有实体风格对齐）：</p><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>info_id</code></td><td>主键</td></tr><tr><td><code>user_id</code></td><td>可空；成功登录时可写入</td></tr><tr><td><code>user_name</code></td><td>用户名</td></tr><tr><td><code>ipaddr</code></td><td>登录地址（IP）</td></tr><tr><td><code>login_location</code></td><td>登录地点（解析结果，可空）</td></tr><tr><td><code>browser</code></td><td>浏览器</td></tr><tr><td><code>os</code></td><td>操作系统</td></tr><tr><td><code>status</code></td><td>状态（与字典一致，如 <code>0</code>/<code>1</code> 成功失败，具体字典类型在实现阶段与 <code>sys_dict_data</code> 对齐）</td></tr><tr><td><code>msg</code></td><td>描述（失败原因、成功简述等）</td></tr><tr><td><code>login_time</code></td><td>访问时间，默认查询按此倒序，索引</td></tr></tbody></table></div><h3 id="_4-2-参数设置-sys-config-内置项" tabindex="-1">4.2 参数设置（<code>sys_config</code>）内置项 <a class="header-anchor vp-link" href="#_4-2-参数设置-sys-config-内置项" aria-label="Permalink to &quot;4.2 参数设置（`sys_config`）内置项&quot;">​</a></h3><p>以下记录通过 <strong>Flyway</strong> 插入，<code>config_type = &#39;1&#39;</code>（系统内置），<code>del_flag = &#39;0&#39;</code>。</p><div class="vp-table"><table><thead><tr><th>config_key</th><th>config_name（示例）</th><th>config_value（默认示例）</th><th>说明</th></tr></thead><tbody><tr><td><code>qc.login.fail-lock-enabled</code></td><td>登录失败锁定开关</td><td><code>true</code></td><td><code>true</code>/<code>false</code>；为 <code>false</code> 时不做计数与锁定，解锁接口仍为幂等成功</td></tr><tr><td><code>qc.login.max-retry</code></td><td>登录失败锁定阈值</td><td><code>5</code></td><td>连续失败达到该次数后拒绝登录并写入锁定状态至缓存</td></tr><tr><td><code>qc.login.lock-minutes</code></td><td>登录锁定时长（分钟）</td><td><code>30</code></td><td>锁定持续时间，与缓存内 <code>lockUntil</code> 一致</td></tr></tbody></table></div><p><strong>内置约束</strong>（沿用现有参数模块）：</p><ul><li>不可删除；编辑时仅允许修改 <code>config_value</code>（及允许的展示字段），禁止改 <code>config_key</code>、<code>config_name</code>、<code>config_type</code> 的篡改绕过（由 <code>SysConfigServiceImpl.update</code> 已强制）。</li></ul><p><strong>备注</strong>：若需「滑动窗口」与「固定窗口」语义，实现阶段在计划中二选一并写死，本设计不强制窗口算法，仅要求行为可测、与 <code>lock-minutes</code> 一致。</p><h2 id="_5-登录失败锁定与-cachemanager" tabindex="-1">5. 登录失败锁定与 CacheManager <a class="header-anchor vp-link" href="#_5-登录失败锁定与-cachemanager" aria-label="Permalink to &quot;5. 登录失败锁定与 CacheManager&quot;">​</a></h2><h3 id="_5-1-抽象与依赖" tabindex="-1">5.1 抽象与依赖 <a class="header-anchor vp-link" href="#_5-1-抽象与依赖" aria-label="Permalink to &quot;5.1 抽象与依赖&quot;">​</a></h3><ul><li>新增组件（命名以代码为准，例如 <code>LoginSecurityCacheService</code> 或 <code>LoginLockService</code>）： <ul><li><strong>仅依赖</strong> <code>org.springframework.cache.CacheManager</code>。</li><li>通过 <code>cacheManager.getCache(&lt;cacheName&gt;)</code> 取得 <code>Cache</code>，使用 <code>get</code> / <code>put</code> / <code>evict</code> 维护条目。</li></ul></li><li><strong>禁止</strong>：在业务类中注入 <code>RedisTemplate</code>、<code>StringRedisTemplate</code>、<code>RedisConnectionFactory</code> 或调用 Jedis/Lettuce API 存储锁定状态。</li></ul><h3 id="_5-2-缓存分区命名" tabindex="-1">5.2 缓存分区命名 <a class="header-anchor vp-link" href="#_5-2-缓存分区命名" aria-label="Permalink to &quot;5.2 缓存分区命名&quot;">​</a></h3><p>与项目既有约定一致，使用 <strong>带 TTL 后缀的缓存名</strong>（参见 <code>DynamicTtlRedisCacheManager</code>、<code>SysConfigServiceImpl</code> 中 <code>sys-config#3600</code>）。</p><ul><li>建议固定一个逻辑分区，例如：<code>qc-login-fail#604800</code>（TTL 取「远大于单次锁定最大合理值」的安全上限，如 7 天；<strong>实际锁定结束时间以条目内字段为准</strong>，避免单缓存 TTL 与 <code>lock-minutes</code> 不一致导致提前失效时逻辑仍正确）。</li><li>缓存 <strong>key</strong>：规范化后的 <code>userName</code>（与 <code>AuthLoginService</code> 中 <code>trim</code> 后一致，大小写策略与登录查询一致）。</li><li>缓存 <strong>value</strong>：可序列化对象（如失败次数、锁定截止时间戳），由 <code>ObjectMapper</code> 序列化（与现有 Redis Cache value 序列化方式兼容）。</li></ul><h3 id="_5-3-与-sys-config-的配合" tabindex="-1">5.3 与 <code>sys_config</code> 的配合 <a class="header-anchor vp-link" href="#_5-3-与-sys-config-的配合" aria-label="Permalink to &quot;5.3 与 `sys_config` 的配合&quot;">​</a></h3><ul><li>阈值与时长：<code>SysConfigService.getConfigValueByKey</code> 读取（已带 Spring Cache，避免每次打库）。</li><li><code>fail-lock-enabled</code> 为 <code>false</code> 时：不递增失败计数、不检查锁定；<strong>解锁</strong>仍执行 <code>evict</code>，幂等。</li></ul><h3 id="_5-4-登录流程中的调用点-逻辑顺序" tabindex="-1">5.4 登录流程中的调用点（逻辑顺序） <a class="header-anchor vp-link" href="#_5-4-登录流程中的调用点-逻辑顺序" aria-label="Permalink to &quot;5.4 登录流程中的调用点（逻辑顺序）&quot;">​</a></h3><ol><li>解析用户名（trim）。</li><li>若启用锁定：检查缓存中是否处于锁定窗口内，若是则抛出业务异常（中文提示），并可选写一条失败日志（避免刷日志可合并策略，实现计划定稿）。</li><li>执行现有验证码逻辑（若开启）。</li><li>调用 <code>authenticate</code>；若抛凭据类失败：递增失败计数，若达阈值则写入锁定至缓存，并写失败日志。</li><li>成功：<code>StpUtil.login</code> 前或后清零该用户失败缓存条目；写成功日志。</li></ol><h3 id="_5-5-解锁接口" tabindex="-1">5.5 解锁接口 <a class="header-anchor vp-link" href="#_5-5-解锁接口" aria-label="Permalink to &quot;5.5 解锁接口&quot;">​</a></h3><ul><li><code>GET /monitor/logininfor/unlock/{userName}</code>：对规范化用户名执行 <strong><code>Cache.evict</code></strong>（及与锁定相关的全部派生 key，若实现中有多 key 则一并清除）；返回统一成功文案（满足需求验收「解锁后有明确成功提示」）。</li></ul><h2 id="_6-后端-登录日志模块" tabindex="-1">6. 后端：登录日志模块 <a class="header-anchor vp-link" href="#_6-后端-登录日志模块" aria-label="Permalink to &quot;6. 后端：登录日志模块&quot;">​</a></h2><h3 id="_6-1-分层" tabindex="-1">6.1 分层 <a class="header-anchor vp-link" href="#_6-1-分层" aria-label="Permalink to &quot;6.1 分层&quot;">​</a></h3><ul><li>建议包路径：<code>io.github.genkidoudou.web.monitor.logininfor</code>（若项目将「监控」挂在 <code>web.system</code> 下，则与现有目录对齐，<strong>二选一保持单一职责包</strong>）。</li><li>Controller / Service / Mapper / Entity / QueryBo / Vo 分层与现有 <code>SysRoleController</code> 等一致。</li></ul><h3 id="_6-2-接口-对外契约" tabindex="-1">6.2 接口（对外契约） <a class="header-anchor vp-link" href="#_6-2-接口-对外契约" aria-label="Permalink to &quot;6.2 接口（对外契约）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/monitor/logininfor/list</code></td><td><code>monitor:logininfor:list</code></td><td>分页 + 条件 + 排序</td></tr><tr><td>POST</td><td><code>/monitor/logininfor/export</code></td><td><code>monitor:logininfor:export</code></td><td>Excel，筛选条件与列表一致</td></tr><tr><td>POST</td><td><code>/monitor/logininfor/remove</code></td><td><code>monitor:logininfor:remove</code></td><td>批量 <code>infoIds</code>（body 或约定参数，与现网批量删除风格一致）</td></tr><tr><td>POST</td><td><code>/monitor/logininfor/clean</code></td><td><code>monitor:logininfor:remove</code></td><td>清空</td></tr><tr><td>GET</td><td><code>/monitor/logininfor/unlock/{userName}</code></td><td><code>monitor:logininfor:unlock</code></td><td>解锁</td></tr></tbody></table></div><ul><li>注解：<code>@Tag</code>、<code>@Operation</code>、<code>@Parameter</code>、<code>@SaCheckPermission</code>。</li><li>校验：Jakarta Validation；业务失败使用项目自定义异常，<strong>禁止</strong> <code>IllegalArgumentException</code> 作为业务信号。</li></ul><h3 id="_6-3-列表查询" tabindex="-1">6.3 列表查询 <a class="header-anchor vp-link" href="#_6-3-列表查询" aria-label="Permalink to &quot;6.3 列表查询&quot;">​</a></h3><ul><li>条件：登录地址（IP）、用户名、状态、登录时间区间。</li><li>排序：默认 <code>login_time</code> 降序；支持按用户名、访问时间排序（参数名与现有分页 BO 对齐）。</li></ul><h2 id="_7-前端-quick-ui" tabindex="-1">7. 前端（<code>quick-ui</code>） <a class="header-anchor vp-link" href="#_7-前端-quick-ui" aria-label="Permalink to &quot;7. 前端（`quick-ui`）&quot;">​</a></h2><ul><li>新增 <code>api/monitor/logininfor</code> 对接上述接口。</li><li>列表页：查询、表格列、多选删除、清空、导出、解锁（对选中行用户名去重后调用解锁）。</li><li>状态列：字典与 <code>status</code> 字段一致（<code>useDict</code> 或项目等价方案）。</li><li>权限：<code>v-hasPermi</code> 或项目等价物，与需求四点一致。</li><li>菜单：Flyway 增加「登录日志」菜单及管理员角色授权（menu_id 与现有迁移错开）。</li></ul><p>参数设置页：无需单独改页面逻辑；内置项随种子出现，删除按钮侧已由后端禁止 + 前端可按 <code>configType</code> 禁用（与参数设置设计一致）。</p><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><ul><li>列表筛选、排序、删除、清空、导出非空。</li><li>连续密码错误达阈值后登录拒绝；解锁后立即可登录（在启用锁定时）。</li><li>关闭 <code>qc.login.fail-lock-enabled</code> 后不计数，解锁仍成功提示。</li><li>内置参数不可删除；修改 <code>config_value</code> 后行为变化符合新值（注意缓存刷新：参数更新已 <code>@CacheEvict</code> 全量清 <code>sys-config#3600</code>，行为应即时生效于下一次读取）。</li></ul><h2 id="_9-后续步骤" tabindex="-1">9. 后续步骤 <a class="header-anchor vp-link" href="#_9-后续步骤" aria-label="Permalink to &quot;9. 后续步骤&quot;">​</a></h2><p>实现前在单独会话中按 brainstorming 收尾流程执行 <strong>writing-plans</strong>，生成可执行任务清单后再编码。</p><hr><p><strong>文档版本</strong>：2026-05-16<br><strong>关联需求</strong>：<code>原始需求/系统管理/登录日志-需求文档.md</code><br><strong>关联规范</strong>：<code>docs/superpowers/specs/2026-05-13-parameter-settings-design.md</code>（内置参数规则）、<code>AGENTS.md</code>（POST 删除语义、异常与 OpenAPI 注解）</p>',50)])])}const p=o(c,[["render",a]]);export{u as __pageData,p as default};
